// Register six variables on the OPC UA Server:
//   ns=1;s=Line-01.Request   (String, initial '')
//   ns=1;s=Line-01.Ack       (String, initial '')
//   ns=1;s=Line-02.Request   ...
//   ns=1;s=Line-02.Ack       ...
//   ns=1;s=Line-03.Request   ...
//   ns=1;s=Line-03.Ack       ...
//
// Per node-red-contrib-opcua convention, send one message per variable
// with topic 'ns=1;s=<Name>;datatype=String;browseName=<Name>' and
// payload { opcuaCommand: 'addVariable' }.

const lines = ['Line-01', 'Line-02', 'Line-03'];
const messages = [];

for (const line of lines) {
    for (const suffix of ['Request', 'Ack']) {
        const varName = `${line}.${suffix}`;
        messages.push({
            topic: `ns=1;s=${varName};datatype=String;browseName=${varName}`,
            payload: { opcuaCommand: 'addVariable' }
        });
        // Initial value write — empty string.
        // Some versions of contrib-opcua require the variable to exist before write;
        // sending the value right after register works because the server processes
        // messages in order on a single inbox.
        messages.push({
            topic: `ns=1;s=${varName}`,
            payload: ''
        });
    }
}

node.status({ fill: 'green', shape: 'dot', text: `registered ${messages.length / 2} vars` });
return [messages];

// Filter messages emitted by the OPC UA Server that correspond to an
// external client writing to one of the Ack variables.
//
// node-red-contrib-opcua emits messages on the OpcUa-Server's output when
// the address space changes. The exact shape varies by version; the safe
// heuristic is:
//   - msg.topic contains 'Line-0X.Ack' (or NodeId form ns=1;s=Line-0X.Ack)
//   - msg.payload is the new value (string in our case)
//
// We only forward Ack writes from clients (line-das). Empty-string writes
// from our own boot initialiser are skipped.

const topic = String(msg.topic || '');
const payload = msg.payload;

// Match nodeId form: ns=1;s=Line-0X.Ack  (X = 1..3)
const nodeIdMatch = topic.match(/^ns=1;s=(Line-0[123])\.Ack$/);
// Match browseName form: Line-0X.Ack
const browseMatch = topic.match(/^(Line-0[123])\.Ack$/);
const lineMatch = nodeIdMatch || browseMatch;

if (!lineMatch) {
    return null;  // not an Ack write
}

// Skip our own boot initial write of '' to avoid log noise.
if (payload === '' || payload === undefined || payload === null) {
    return null;
}

const line = lineMatch[1];

let parsed = null;
let parseError = null;
try {
    parsed = typeof payload === 'string' ? JSON.parse(payload) : payload;
} catch (e) {
    parseError = e.message;
}

const out = {
    topic: `ack/${line}`,
    payload: {
        line,
        raw: payload,
        parsed,
        parseError,
        receivedAt: new Date().toISOString()
    }
};

node.status({ fill: 'blue', shape: 'dot', text: `${line} ack` });
return out;

// Emit a single-line console log for each Ack — visible in `docker logs command-center`.
const p = msg.payload || {};
const rawLen = typeof p.raw === 'string' ? p.raw.length : 0;
const cmd_id = p.parsed && p.parsed.cmd_id;
const result = p.parsed && p.parsed.result;
const accepted = p.parsed && p.parsed.accepted;

const summary = p.parseError
    ? `parseError=${p.parseError} rawLen=${rawLen}`
    : `cmd_id=${cmd_id} accepted=${accepted} result=${result}`;

console.log(`[ACK] line=${p.line} ${summary}`);
return null;

// Useful diagnostic — prints the public endpoint URL clients should use.
const host = 'command-center';
const port = (env.get('OPCUA_SERVER_PORT') || '5160');
const url = `opc.tcp://${host}:${port}/UA/CommandCenter`;
console.log(`[OPC UA Server] endpoint: ${url}`);
node.status({ fill: 'grey', shape: 'ring', text: url });
return null;
